#!/usr/bin/env bash
# US-025 LC-6a dev/report run (NOT a registered gate run): one ORIGINAL SDK run with loop close OFF (poke lc=0) and recorded inputs, for the null arm.
# Output build/slam-refact-final-20261025/lc6a/orig/<scenario>/<label> (run_lc6a.mjs, generated by make_run_lc6a.py). Resource precheck and the shared Chromium lock
# (taken first, see below; otherwise as in tools/re/runtime/us025/golden-run.sh):
#   MAX_BUILDS (default 0): top-level builds other lanes may have running (the override is written to the precheck file);
#   WAIT_MIN (default 0) / LOAD_MAX (default unset): keep re-checking every 20 s until the precheck passes and the 1-minute load average is below LOAD_MAX
#   (the original SDK is load sensitive, us026/README.md NR-BA-2).
#   bash run_original_lc0.sh <scenario> <label>
set -u
cd "$(dirname "$0")/../../../../.."
[ $# -eq 2 ] || { echo "usage: run_original_lc0.sh <scenario> <label>" >&2; exit 2; }
s=$1 label=$2
OUT_ROOT=build/slam-refact-final-20261025/lc6a/orig
mkdir -p "$OUT_ROOT/$s"
now() { date +%Y-%m-%dT%H:%M:%S%z; }
started=$(now)
pre=$OUT_ROOT/$s/precheck-$label.txt
{ echo "started $started"; echo "loadavg $(cat /proc/loadavg)"; df -h / | tail -1; echo "PRECHECK_MAX_HEADLESS=0 PRECHECK_MAX_BUILDS=${MAX_BUILDS:-0} LOAD_MAX=${LOAD_MAX:-<unset>}"; echo "inherited (and removed) PRECHECK_* variables: $(env | grep '^PRECHECK_' | tr '\n' ' ')"; } > "$pre"
deadline=$(( $(date +%s) + ${WAIT_MIN:-0} * 60 ))
# The shared Chromium lock is taken BEFORE the precheck (other lanes run Chromium back to back, so a precheck outside the lock almost never sees zero
# headless browsers); the precheck then runs while we hold the lock, so whatever it counts is not a lane that honours the lock.
exec 9> build/c1-chromium.lock
while :; do
  ok=1
  if [ -n "${LOAD_MAX:-}" ]; then
    awk -v l="$(cut -d' ' -f1 /proc/loadavg)" -v m="$LOAD_MAX" 'BEGIN{exit !(l < m)}' || { ok=0; echo "load $(cut -d' ' -f1 /proc/loadavg) >= LOAD_MAX $LOAD_MAX" >> "$pre"; }
  fi
  if [ $ok = 1 ]; then
    flock -w 120 9 || ok=0
  fi
  if [ $ok = 1 ]; then
    # every inherited PRECHECK_* variable is removed (a caller's PRECHECK_MAX_DISK_PCT=97 would silently relax the check); only the two below are set
    env $(env | cut -d= -f1 | grep '^PRECHECK_' | sed 's/^/-u /') PRECHECK_MAX_HEADLESS=0 PRECHECK_MAX_BUILDS=${MAX_BUILDS:-0} \
      bash slam_refact/docs/design/tools/lane-precheck.sh >> "$pre" 2>&1 || ok=0
    if [ $ok = 1 ] && [ -n "${LOAD_MAX:-}" ]; then
      awk -v l="$(cut -d' ' -f1 /proc/loadavg)" -v m="$LOAD_MAX" 'BEGIN{exit !(l < m)}' || ok=0
    fi
    [ $ok = 1 ] || flock -u 9
  fi
  [ $ok = 1 ] && break
  if [ "$(date +%s)" -ge "$deadline" ]; then
    printf '%s\t%s\t%s\t%s\tPRECHECK-BLOCKED\n' "$started" "$(now)" "$s" "$label" >> "$OUT_ROOT/run-log.tsv"; tail -12 "$pre" >&2; exit 3
  fi
  sleep 20
done
{ echo "go (lock held) $(now)"; echo "loadavg $(cat /proc/loadavg)"; } >> "$pre"
node slam_refact/tools/harness/us025/lc6a/run_lc6a.mjs --scenario "$s" --label "$label" --out-root "$OUT_ROOT" \
  --memprobe --memprobe-lc --memprobe-detail 12 --record-inputs --poke '{"lc":0}' 9>&-
rc=$?
st=$(python3 -c "import json,sys; print(json.load(open(sys.argv[1])).get('status'))" "$OUT_ROOT/$s/$label/meta.json" 2>/dev/null || echo NO-META)
printf '%s\t%s\t%s\t%s\trc=%s\t%s\n' "$started" "$(now)" "$s" "$label" "$rc" "$st" >> "$OUT_ROOT/run-log.tsv"
exit $rc
